<script setup lang="ts">
import { computed,h,onMounted,ref } from 'vue'
import { NAlert,NButton,NDataTable,NIcon,NSelect,NTag,useMessage } from 'naive-ui'
import { Download,Filter,ArrowUpRight,ArrowDownRight,Receipt } from '@vicons/tabler'
import { api,bytes,stamp } from '../api'
import {calendarRange} from '../calendar'
const props=defineProps<{me:any;zone:string;userId?:number}>();const message=useMessage()
const rows=ref<any[]>([]),meta=ref<any>({}),busy=ref(false),error=ref(''),users=ref<any[]>([]),nodes=ref<any[]>([]),userID=ref<number|null>(props.userId??null),nodeID=ref<number|null>(null),timezone=ref(props.zone),grain=ref('day')
const initialRange=calendarRange(props.zone,7);const from=ref(initialRange.from),to=ref(initialRange.to)
const zones=['UTC','Asia/Shanghai','Asia/Hong_Kong','Asia/Tokyo','America/Los_Angeles','Europe/London'].map(x=>({label:x,value:x}))
function query(){const q=new URLSearchParams({from:from.value,to:to.value,timezone:timezone.value,grain:grain.value});if(userID.value)q.set('user_id',String(userID.value));if(nodeID.value)q.set('node_id',String(nodeID.value));return q.toString()}
async function load(){busy.value=true;error.value='';try{meta.value=await api('/api/usage?'+query());rows.value=meta.value.rows}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function quick(days:number,offset=0){const range=calendarRange(timezone.value,days,offset);from.value=range.from;to.value=range.to;load()}
async function download(){try{const response=await fetch('/api/usage/export?'+query());if(!response.ok){const data=await response.json();throw new Error(data.error)}const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='luma-usage.csv';a.click();URL.revokeObjectURL(url)}catch(e){message.error((e as Error).message)}}
const total=computed(()=>rows.value.reduce((a,r)=>({up:a.up+Number(r.up_bytes),down:a.down+Number(r.down_bytes),billed:a.billed+Number(r.billed_bytes)}),{up:0,down:0,billed:0}))
const columns=computed(()=>[{title:'采集窗口归档时间',key:'bucket',minWidth:180},{title:'节点',key:'node_name',minWidth:130},...(props.me.role==='admin'?[{title:'用户',key:'user_email',minWidth:190}]:[]),{title:'上传',key:'up_bytes',minWidth:110,render:(r:any)=>bytes(r.up_bytes)},{title:'下载',key:'down_bytes',minWidth:110,render:(r:any)=>bytes(r.down_bytes)},{title:'计费用量',key:'billed_bytes',minWidth:120,render:(r:any)=>bytes(r.billed_bytes)},{title:'数据质量',key:'legacy',minWidth:110,render:(r:any)=>h(NTag,{size:'small',bordered:false,type:r.legacy?'warning':'success'},()=>r.legacy?'含旧协议':'可靠批次')}])
onMounted(async()=>{load();if(props.me.role==='admin'){try{[users.value,nodes.value]=await Promise.all([api('/api/admin/users'),api('/api/admin/nodes')])}catch(e){message.error((e as Error).message)}}})
</script>
<template><div class="page-heading"><div><span class="eyebrow">TRAFFIC</span><h1>流量统计</h1><p>按用户、节点与日期查询原始和计费用量。</p></div><n-button secondary @click="download"><template #icon><n-icon :component="Download"/></template>导出 CSV</n-button></div><article class="surface filters"><div class="quick-ranges"><button @click="quick(1)">今天</button><button @click="quick(1,1)">昨天</button><button @click="quick(7)">近 7 天</button><button @click="quick(30)">近 30 天</button><span class="muted small">最多查询 366 天</span></div><div class="filter-grid"><label>开始日期<input v-model="from" type="date"/></label><label>结束日期<input v-model="to" type="date"/></label><label v-if="me.role==='admin'">用户<n-select v-model:value="userID" clearable filterable placeholder="全部用户" :options="users.map(x=>({label:x.email,value:x.id}))"/></label><label v-if="me.role==='admin'">节点<n-select v-model:value="nodeID" clearable filterable placeholder="全部节点" :options="nodes.map(x=>({label:x.name,value:x.id}))"/></label><label>统计时区<n-select v-model:value="timezone" :options="zones"/></label><label>聚合粒度<n-select v-model:value="grain" :options="[{label:'按小时',value:'hour'},{label:'按天',value:'day'},{label:'按月',value:'month'}]"/></label><n-button type="primary" :loading="busy" @click="load"><template #icon><n-icon :component="Filter"/></template>查询</n-button></div></article><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><n-alert v-if="meta.truncated" type="warning" class="space-bottom">结果超过 2000 组，请缩小范围以查看或导出完整数据。</n-alert><section class="stat-grid three"><article class="stat-card"><span class="stat-label">本次查询 · 上传</span><n-icon class="stat-icon" :component="ArrowUpRight"/><strong>{{bytes(total.up)}}</strong><small>原始上传字节</small></article><article class="stat-card"><span class="stat-label">本次查询 · 下载</span><n-icon class="stat-icon" :component="ArrowDownRight"/><strong>{{bytes(total.down)}}</strong><small>原始下载字节</small></article><article class="stat-card"><span class="stat-label">本次查询 · 计费用量</span><n-icon class="stat-icon" :component="Receipt"/><strong>{{bytes(total.billed)}}</strong><small>已应用首次入账时的倍率</small></article></section><article class="surface"><div class="section-heading"><div><h2>用量明细</h2><p>{{rows.length}} 组记录 · {{timezone}}</p></div><span class="muted small">更新于 {{stamp(meta.updated_at)}}</span></div><n-data-table :columns="columns" :data="rows" :loading="busy" :bordered="false" :scroll-x="me.role==='admin'?1100:900" :pagination="{pageSize:15}"/><p class="table-note">跨日采集窗口按结束时间归档；旧协议按服务器接收时间估算，不保证重试去重。CSV 保留精确字节数，可用 Excel 打开。</p></article></template>
